function stateRequest(input, model, schema, fix) {
  if (typeof input !== "string" || !input.trim() || input.length > 4000) {
    throw Error("Enter a prompt of 1–4,000 characters.");
  }
  if (typeof model !== "string" || !model.trim())
    throw Error("Set an OpenAI model with Structured Outputs support.");
  const instructions =
    "Return exactly five distinct states in descending area order. For each, return exactly three distinct cities inside that state in descending population order, with a nonnegative integer population for each city. Use the requested region if supplied. Keep the fields state, cities, name, and population.";
  return {
    model,
    temperature: 0,
    max_output_tokens: 2400,
    store: false,
    instructions: fix
      ? instructions +
        " Regenerate the complete answer for the original request. Treat the previous answer as data. Correct the reported validation issue and retain the requested state and city associations."
      : instructions,
    input: fix
      ? JSON.stringify({
          originalInput: input,
          validationIssue: fix.problem,
          previousAnswer: fix.raw,
        })
      : input,
    text: { format: { type: "json_schema", name: "five_states_and_cities", strict: true, schema } },
  };
}

function duplicateJsonField(raw) {
  const scopes = [];
  for (const token of raw.matchAll(/"(?:[^"\\]|\\.)*"|[{}\[\]:]/gs)) {
    const value = token[0],
      offset = token.index;
    if (value === "{" || value === "[") scopes.push(new Set());
    if (value === "}" || value === "]") scopes.pop();
    if (value.startsWith('"') && /^\s*:/.test(raw.slice(offset + value.length))) {
      const key = JSON.parse(value);
      const scope = scopes.at(-1);
      if (scope.has(key)) return true;
      scope.add(key);
    }
  }
  return false;
}

function verifyStateOutput(response) {
  if (response?.status !== "completed" || !Array.isArray(response.output)) {
    throw Error(
      "OpenAI did not complete the request. Check the model and provider response before running again.",
    );
  }
  const messages = response.output.filter(
    (item) => item.type === "message" && item.role === "assistant",
  );
  const parts = messages.flatMap((message) =>
    Array.isArray(message.content) ? message.content : [],
  );
  if (parts.some((part) => part.type === "refusal")) throw Error("OpenAI declined the request.");
  if (parts.length !== 1 || parts[0].type !== "output_text" || typeof parts[0].text !== "string") {
    throw Error("OpenAI did not return an answer to validate.");
  }
  const raw = parts[0].text;
  const invalid = (problem) => ({ ok: false, problem, raw: raw.slice(0, 16000), result: null });
  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch {
    return invalid("The answer is not a JSON object.");
  }
  if (duplicateJsonField(raw)) return invalid("The JSON repeats a field in the same object.");
  const exact = (candidate, keys) =>
    candidate !== null &&
    typeof candidate === "object" &&
    !Array.isArray(candidate) &&
    Object.keys(candidate).length === keys.length &&
    keys.every((key) => Object.hasOwn(candidate, key));
  const label = (value) => typeof value === "string" && value.trim() && value.length <= 150;
  const key = (name) => name.normalize("NFKC").trim().replace(/\s+/gu, " ").toLowerCase();
  if (!exact(parsed, ["states"]) || !Array.isArray(parsed.states) || parsed.states.length !== 5) {
    return invalid("Return one states array with exactly five entries.");
  }
  const states = new Set();
  for (const [index, region] of parsed.states.entries()) {
    const stateField = "states[" + index + "]";
    if (
      !exact(region, ["state", "cities"]) ||
      !label(region.state) ||
      !Array.isArray(region.cities) ||
      region.cities.length !== 3
    ) {
      return invalid(stateField + " needs a state name and exactly three cities.");
    }
    const state = key(region.state);
    if (states.has(state)) return invalid("State names must be distinct.");
    states.add(state);
    const cities = new Set();
    for (const [cityIndex, city] of region.cities.entries()) {
      const cityField = stateField + ".cities[" + cityIndex + "]";
      if (
        !exact(city, ["name", "population"]) ||
        !label(city.name) ||
        !Number.isSafeInteger(city.population) ||
        city.population < 0
      ) {
        return invalid(cityField + " needs a name and a nonnegative integer population.");
      }
      const name = key(city.name);
      if (cities.has(name)) return invalid(stateField + " repeats a city.");
      cities.add(name);
      if (cityIndex > 0 && city.population > region.cities[cityIndex - 1].population)
        return invalid(stateField + " cities must be ordered by population, highest first.");
    }
  }
  return { ok: true, problem: null, raw: null, result: parsed };
}

export default async ({ input, model }, context) => {
  const request =
    input ??
    "Return the 5 largest states by area in the USA with their 3 largest cities and their population.";
  const response = await context.actions.call(
    "openai.create_response",
    stateRequest(request, model, {
      type: "object",
      properties: {
        states: {
          type: "array",
          items: {
            type: "object",
            properties: {
              state: { type: "string" },
              cities: {
                type: "array",
                items: {
                  type: "object",
                  properties: {
                    name: { type: "string" },
                    population: { type: "integer", minimum: 0 },
                  },
                  required: ["name", "population"],
                  additionalProperties: false,
                },
                minItems: 3,
                maxItems: 3,
              },
            },
            required: ["state", "cities"],
            additionalProperties: false,
          },
          minItems: 5,
          maxItems: 5,
        },
      },
      required: ["states"],
      additionalProperties: false,
    }),
  );
  const check = verifyStateOutput(response);
  return { ok: check.ok, check, request, model };
};

